/**
 * Stepper — pasos de un recorrido (Mi Garaje, mi-garaje-lab · Flujo Publicar / Valorizar).
 * Barra: nombres arriba, ProgressBar de Concorde partida en un tramo por paso (el actual a la mitad) y los pasos hechos
 * con check, como botones para volver. En móvil (≤ 767 px) muestra solo el paso actual con «paso N de M».
 */
import type { CSSProperties, JSX } from "react";
import ProgressBar from "@/concorde/components/ProgressBar";
import CheckIcon from "@/concorde/components/CheckIcon";

export const STEPPER_CSS = String.raw`
/* Barra: ProgressBar en tramos (--n pasos) + nombres; hecho = check y se puede tocar. */
.fl-steps { display:grid; gap:10px; }
.fl-steps ol { order:-1; list-style:none; margin:0; padding:0; display:grid; grid-auto-flow:column; grid-auto-columns:1fr; column-gap:6px; align-items:center; min-height:24px; }
.fl-steps li { display:flex; align-items:center; gap:8px; min-width:0; font-size:.8125rem; font-weight:500; white-space:nowrap; color:var(--f-muted, #6B6878); }
.fl-steps li > span { display:grid; place-items:center; width:22px; height:22px; border-radius:50%; font-size:.75rem; font-weight:700; background:none; box-shadow:inset 0 0 0 1.5px #D9D4E5; color:#8A8797; }
.fl-steps li.is-now { color:#3B1782; font-weight:700; }
.fl-steps li.is-now > span { color:#fff; background:#ED8936; box-shadow:0 0 0 4px rgba(237,137,54,.18); }
.fl-steps li button { all:unset; cursor:pointer; display:inline-flex; align-items:center; gap:8px; color:var(--f-ink, #3B1782); border-radius:8px; padding:2px 6px; margin:-2px -6px; }
.fl-steps li.is-done button { color:#3B1782; font-weight:600; }
.fl-steps li.is-done svg { color:#ED8936; }
.fl-steps li button:hover { background:var(--f-tint, #F5F0FF); text-decoration:underline; text-underline-offset:3px; }
.fl-steps li button:focus-visible { outline:2px solid var(--f-focus, #8460E5); outline-offset:2px; }
.fl-steps .pprogbar { height:6px; border-radius:9999px; background:#E7E3F0; box-shadow:none;
  --seg:calc((100% - (var(--n, 3) - 1) * 6px) / var(--n, 3));
  -webkit-mask:repeating-linear-gradient(90deg, #000 0 var(--seg), transparent var(--seg) calc(var(--seg) + 6px));
          mask:repeating-linear-gradient(90deg, #000 0 var(--seg), transparent var(--seg) calc(var(--seg) + 6px)); }
.fl-steps .pprogbar__fill { background:linear-gradient(90deg, #F4AC59 0%, #ED8936 30%, #8460E5 100%); transition:width .6s cubic-bezier(.16,1,.3,1); }
.fl-steps__of { display:none; }
/* Móvil: solo el paso actual con «paso N de M»; la barra de tramos muestra el resto. */
@media (max-width:767px) {
  .fl-steps ol { grid-auto-flow:row; }
  .fl-steps li:not(.is-now) { display:none; }
  .fl-steps .fl-steps__of { display:inline; font-size:.75rem; font-weight:500; color:#6B6878; }
}

@media (prefers-reduced-motion:reduce) { .fl-steps .pprogbar__fill { transition:none; } }
`;

export interface StepperProps {
  /** Nombres de los pasos, en orden. */
  steps: string[];
  /** Paso actual, desde 0. */
  current: number;
  /** Los pasos hechos son botones que la llaman con su índice para volver a ese paso. */
  onGo: (step: number) => void;
}

export function Stepper({ steps, current, onGo }: StepperProps): JSX.Element {
  const styles = <style href="concorde-stepper" precedence="default">{STEPPER_CSS}</style>;
  const cls = (i: number) => i < current ? "is-done" : i === current ? "is-now" : "";
  // El tramo del paso actual va a la mitad (en curso); los hechos, llenos.
  return <>{styles}<div className={`fl-steps${steps.length > 3 ? " fl-steps--long" : ""}`} style={{ "--n": steps.length } as CSSProperties}>
    <ProgressBar value={((current + 0.5) / steps.length) * 100} />
    <ol aria-label={`Paso ${current + 1} de ${steps.length}`}>{steps.map((s, i) => <li key={s} className={cls(i)} aria-current={i === current ? "step" : undefined}>
      {i < current ? <button type="button" onClick={() => onGo(i)} aria-label={`Volver a ${s}`}><CheckIcon size={16} />{s}</button>
        : <><span>{i + 1}</span>{s}{i === current ? <small className="fl-steps__of">· paso {i + 1} de {steps.length}</small> : null}</>}</li>)}</ol>
  </div></>;
}

export default Stepper;

"use client";

/**
 * ProgressBar — Generado por Concorde
 * Fuente: Figma VOYAGER · "Progressbar - Tiempo de bid" (3182:12947)
 *
 * Barra de progreso (track hundido): top recto, esquinas inferiores redondeadas
 * (radio 13), fondo negro 22% con inner-shadows. El relleno (`value` 0-100) usa
 * la gradiente primary (white → #F4AC59 → #8460E5 → white · VYStrokes1). Copia
 * del SVG. Solo `value` — sin estilos editables.
 */

import type { JSX } from "react";

export type ProgressBarVariant = "default" | "rainbow" | "white";

export interface ProgressBarProps {
  /** Progreso 0-100 (default 60) */
  value?: number;
  /** Relleno: "default" (gradiente primary), "rainbow" (white→magenta→rosa) o "white" (blanco sólido). Default "default". */
  variant?: ProgressBarVariant;
  /**
   * Duración (ms) de la transición de ancho al cambiar `value`. Si se omite usa
   * la del CSS (0.3s). Útil para animar un llenado continuo (p. ej. 3000ms lineal).
   */
  transitionMs?: number;
  "aria-label"?: string;
  className?: string;
}

const STYLE_ID = "concorde-progressbar-styles";

const PROGRESSBAR_STYLES = `
.pprogbar {
  position: relative;
  width: 100%;
  height: 22px;
  border-radius: 0 0 13px 13px;
  overflow: hidden;
  background: rgba(0,0,0,0.22);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.06), inset 0 2px 4px rgba(0,0,0,0.35);
}
.pprogbar__fill {
  position: absolute;
  left: 0;
  top: 0;
  height: 100%;
  background: linear-gradient(135deg, #FFFFFF 0%, #F4AC59 22%, #8460E5 74.5%, #FFFFFF 100%);
  transition: width 0.3s cubic-bezier(0.3,0,0,1);
}
/* Rainbow horizontal (no diagonal): white → lila → magenta → rosa */
.pprogbar__fill--rainbow {
  background: linear-gradient(90deg, #FFFFFF 0%, #F2CCFF 25%, #CC00FF 60%, #FF0066 100%);
  box-shadow: 0 0 6px rgba(255,255,255,0.8), 0 0 14px rgba(204,0,255,0.9), 0 0 30px rgba(255,0,102,0.5);
}
/* Blanco sólido (fases de carga: recibiendo participantes / inicio extendido) */
.pprogbar__fill--white {
  background: #ffffff;
  box-shadow: 0 0 6px rgba(255,255,255,0.7);
}
@media (prefers-reduced-motion: reduce) { .pprogbar__fill { transition: none; } }
`;

let _stylesInjected = false;

export default function ProgressBar({
  value = 60,
  variant = "default",
  transitionMs,
  "aria-label": ariaLabel,
  className = "",
}: ProgressBarProps): JSX.Element {
  if (typeof document !== "undefined" && !_stylesInjected) {
    if (!document.getElementById(STYLE_ID)) {
      const el = document.createElement("style");
      el.id = STYLE_ID;
      el.textContent = PROGRESSBAR_STYLES;
      document.head.appendChild(el);
    }
    _stylesInjected = true;
  }

  const clamped = Math.max(0, Math.min(100, value));

  return (
    <>
      <style id={`${STYLE_ID}-ssr`} suppressHydrationWarning dangerouslySetInnerHTML={{ __html: PROGRESSBAR_STYLES }} />
      <div
        className={`pprogbar ${className}`.trim()}
        role="progressbar"
        aria-valuenow={clamped}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-label={ariaLabel ?? "Tiempo de bid"}
      >
        <div
          className={`pprogbar__fill ${variant !== "default" ? `pprogbar__fill--${variant}` : ""}`.trim()}
          style={{ width: `${clamped}%`, ...(transitionMs != null ? { transition: `width ${transitionMs}ms linear` } : {}) }}
        />
      </div>
    </>
  );
}

/**
 * CheckIcon — Generado por Concorde
 * Fuente: Figma VOYAGER · "Vector" (1435:12195)
 *
 * Círculo relleno con gradiente naranja (#FF9639 → #EF852E → #BE3D00) y un
 * check recortado (knockout) que se ve blanco sobre superficies claras.
 * Copia exacta del path del SVG. Tamaño personalizable como PriceIcon.
 */

import { useId } from "react";
import type { JSX } from "react";

export interface CheckIconProps {
  /** Tamaño en px o alias: "sm" (16) · "md" (20). Default 20. */
  size?: "sm" | "md" | number;
  /** Texto accesible. Si se omite, el icono es decorativo (aria-hidden). */
  title?: string;
  className?: string;
}

const SIZES: Record<"sm" | "md", number> = { sm: 16, md: 20 };

export default function CheckIcon({ size = 20, title, className = "" }: CheckIconProps): JSX.Element {
  const uid = useId().replace(/:/g, "-");
  const gradId = `checkicon-grad-${uid}`;
  const px = typeof size === "number" ? size : SIZES[size];

  return (
    <svg
      width={px}
      height={px}
      viewBox="0 0 20 20"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={className}
      role={title ? "img" : undefined}
      aria-hidden={title ? undefined : true}
    >
      {title ? <title>{title}</title> : null}
      <path
        fillRule="evenodd"
        clipRule="evenodd"
        d="M10 20C15.5228 20 20 15.5228 20 10C20 4.47715 15.5228 0 10 0C4.47715 0 0 4.47715 0 10C0 15.5228 4.47715 20 10 20ZM8.7785 10.7609L6.73408 8.7093C6.34797 8.3249 5.68605 8.3249 5.29993 8.7093L4.50011 9.5057C4.114 9.8901 4.114 10.5492 4.50011 10.9336L8.0028 14.4485C8.2424 14.6871 8.5882 14.7776 8.9085 14.72C9.2105 14.7794 9.5356 14.6817 9.7613 14.427L15.5149 7.96363C15.881 7.55044 15.881 6.84213 15.5149 6.42895L14.7564 5.57307C14.3903 5.15989 13.7627 5.15989 13.3965 5.57307L8.7785 10.7609Z"
        fill={`url(#${gradId})`}
      />
      <defs>
        <linearGradient id={gradId} x1="10" y1="0" x2="10" y2="20" gradientUnits="userSpaceOnUse">
          <stop stopColor="#FF9639" />
          <stop offset="0.4" stopColor="#EF852E" />
          <stop offset="1" stopColor="#BE3D00" />
        </linearGradient>
      </defs>
    </svg>
  );
}
